SELECT COUNT(*) FROM votes as v, comments as c, postLinks as pl, users as u, posts as p WHERE p.Id = pl.PostId AND u.Id = c.UserId AND p.Id = c.PostId AND u.Id = v.UserId AND v.CreationDate>=CAST('2010-07-27 00:00:00' AS TIMESTAMP) AND c.CreationDate<=CAST('2014-09-11 13:24:22' AS TIMESTAMP) AND pl.CreationDate>=CAST('2010-08-13 11:42:08' AS TIMESTAMP) AND pl.CreationDate<=CAST('2014-08-29 00:27:05' AS TIMESTAMP)
